import{_ as r,o as a,c as o,a2 as s}from"./chunks/framework.CHeM0PsO.js";const c=JSON.parse('{"title":"案例 07 · 元气森林 × 分众「众小智」（逆向拆解）","description":"","frontmatter":{"outline":"deep"},"headers":[],"relativePath":"cases/case-07-yuanqi-fenzhong.md","filePath":"cases/case-07-yuanqi-fenzhong.md","lastUpdated":1785844806000}'),d={name:"cases/case-07-yuanqi-fenzhong.md"};function e(n,t,l,g,h,i){return a(),o("div",null,[...t[0]||(t[0]=[s('<h1 id="案例-07-·-元气森林-×-分众「众小智」-逆向拆解" tabindex="-1">案例 07 · 元气森林 × 分众「众小智」（逆向拆解） <a class="header-anchor" href="#案例-07-·-元气森林-×-分众「众小智」-逆向拆解" aria-label="Permalink to &quot;案例 07 · 元气森林 × 分众「众小智」（逆向拆解）&quot;">​</a></h1><blockquote><p><strong>一句话</strong>：它的看点不是「用 AI 做广告」，而是<strong>一条创意裂变成 N 个场景版本</strong>——而这件事在梯媒上的逻辑，和信息流完全不同。</p></blockquote><div class="warning custom-block"><p class="custom-block-title">先说清楚这篇的性质</p><p>这是对<strong>行业媒体公开报道的逆向拆解</strong>，不是项目复盘。</p><ul><li>信息来源为行业媒体报道，<strong>未观看任何一版成片</strong>，因此不做画面与分镜分析。</li><li>成本与周期数字为<strong>品牌方 / 服务商对外口径</strong>，未经第三方核实。<strong>这类数字通常是最乐观的算法</strong>，引用时务必打折，理由见 ③。</li><li>分众「众小智」是分众传媒的营销垂类模型与 AI 智能体，为第三方产品。</li></ul></div><div class="danger custom-block"><p class="custom-block-title">时间与可信度</p><p>报道时间为 <strong>2026 年</strong>，是本站三篇公开案例里<strong>相对最新</strong>的一个。</p><p>但代价是：<strong>公开细节最少。<strong>没有 prompt、没有链路、没有出片率，只有结果数字。所以这篇能拆的是</strong>打法</strong>，不是<strong>做法</strong>。</p><p>对比 <a href="/cases/case-06-kalshi-veo">案例 06 · Kalshi</a>——那篇时间更早（2025 年 6 月），但创作者公开了全部流程。<strong>信息量和新鲜度往往是反着的。</strong></p></div><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td>品类</td><td>无糖气泡水</td></tr><tr><td>交付形态</td><td>梯媒广告，多版本</td></tr><tr><td>投放渠道</td><td>分众电梯媒体（写字楼 / 社区）</td></tr><tr><td>工期</td><td>缩短至 3 天（口径）</td></tr><tr><td>成本</td><td>较传统实拍降低 80%（口径）</td></tr><tr><td>出片率</td><td><strong>未公开</strong></td></tr></tbody></table><hr><h2 id="_1-真正的看点-一条创意-两套话术" tabindex="-1">① 真正的看点：一条创意，两套话术 <a class="header-anchor" href="#_1-真正的看点-一条创意-两套话术" aria-label="Permalink to &quot;① 真正的看点：一条创意，两套话术&quot;">​</a></h2><p>公开报道里给出的两个版本是这样的：</p><table tabindex="0"><thead><tr><th>场景</th><th>文案</th><th>对应的人群状态</th></tr></thead><tbody><tr><td><strong>写字楼</strong></td><td>上班困了？喝口元气森林醒醒神</td><td>疲惫、需要提神、在工作情境里</td></tr><tr><td><strong>社区</strong></td><td>周末宅家，元气气泡水配电影更快乐</td><td>放松、休闲、在家庭情境里</td></tr></tbody></table><p>同一个产品、同一个品牌、同一支创意骨架，<strong>因为电梯所在的楼是写字楼还是住宅楼，说的话完全不一样。</strong></p><div class="tip custom-block"><p class="custom-block-title">这才是这个案例的价值所在</p><p>「AI 能做广告」在 2026 年已经不是新闻。真正值得记的是：<strong>AI 让「按场景定制」这件事从不划算变成了划算。</strong></p><p>传统实拍下，为写字楼和社区各拍一版，等于成本翻倍——所以大家都拍一版通用的，牺牲精准度。<strong>AI 把边际成本压到接近零之后，这个妥协就没必要了。</strong></p></div><hr><h2 id="_2-梯媒的多版本-和信息流的多版本不是一回事" tabindex="-1">② 梯媒的多版本，和信息流的多版本不是一回事 <a class="header-anchor" href="#_2-梯媒的多版本-和信息流的多版本不是一回事" aria-label="Permalink to &quot;② 梯媒的多版本，和信息流的多版本不是一回事&quot;">​</a></h2><p>这是本篇最需要说清楚的一点，也是最容易被混淆的地方。</p><table tabindex="0"><thead><tr><th></th><th>信息流多版本</th><th>梯媒多版本</th></tr></thead><tbody><tr><td><strong>目的</strong></td><td><strong>测试</strong>——找出哪一版效果好</td><td><strong>适配</strong>——每一版服务不同的人</td></tr><tr><td><strong>版本关系</strong></td><td>互相竞争，优胜劣汰</td><td>并行共存，各归各的场景</td></tr><tr><td><strong>变量</strong></td><td>单变量（只改钩子 / 只改文案）</td><td>整体重写（人群不同，说法就得不同）</td></tr><tr><td><strong>判断依据</strong></td><td>投放数据</td><td>场景与人群的先验判断</td></tr><tr><td><strong>观看状态</strong></td><td>可随时划走，前 3 秒定生死</td><td><strong>强制观看</strong>，不用抢开头</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">这一条修正了本站的一处归类</p><p><a href="/method/ab-testing">A/B 创意批量测试</a> 那一页讲的是<strong>测试型批量</strong>——单变量、比输赢、看数据。</p><p>这个案例是<strong>适配型批量</strong>——多变量、不比输赢、靠先验判断分发。</p><p>**两者都叫「批量生成多版本」，但目的完全相反，方法也不能互换。**把梯媒的场景版本拿去做 A/B 测试，会得到一堆无法归因的结论——因为你同时改了太多东西。</p></div><h3 id="电梯场景还有一个特殊性" tabindex="-1">电梯场景还有一个特殊性 <a class="header-anchor" href="#电梯场景还有一个特殊性" aria-label="Permalink to &quot;电梯场景还有一个特殊性&quot;">​</a></h3><p>信息流里，前 3 秒不抓人就没了。<strong>电梯里没有「划走」这个动作</strong>——观众被物理地困在一个封闭空间里，广告是重复循环播放的。</p><p>这意味着梯媒创意的结构和短视频<strong>根本不同</strong>：</p><ul><li>不需要钩子前置</li><li>重复是优点不是缺点（循环播放会强化记忆）</li><li>可以更依赖文案，因为观众有时间读</li></ul><p>**如果把信息流那套「3 秒钩子」直接搬到梯媒，是用错了地方。**这一点在 <a href="/method/ad-formats">片型图谱</a> 的投放场景表里值得补一行。</p><hr><h2 id="_3-那个-80-该怎么看" tabindex="-1">③ 那个 80% 该怎么看 <a class="header-anchor" href="#_3-那个-80-该怎么看" aria-label="Permalink to &quot;③ 那个 80% 该怎么看&quot;">​</a></h2><div class="danger custom-block"><p class="custom-block-title">这个数字要打折，理由有三条</p><p><strong>一、分母可能被放大。</strong>「传统实拍」是拿哪一档比？拍一支正经 TVC 要几百万，但拍一支梯媒 15 秒的简易版可能只要十几万。<strong>分母取值不同，降幅可以从 80% 变成 30%。</strong></p><p>**二、口径通常不含人力。**AI 生成的直接消耗确实低，但筛选、修改、审校的人工时间往往不计入。<a href="/guide/landscape">AI 创意广告全景</a> 里说过：<strong>AI 真正省的是试错成本和排期，不一定是总成本。</strong></p><p>**三、这是服务商的宣传口径。**分众要卖「众小智」，品牌方乐于展示效率。<strong>双方都没有把数字往下压的动机。</strong></p></div><p><strong>那这个数字还有用吗？有用，但只能这么用：</strong></p><blockquote><p>把它当作<strong>方向性信号</strong>——「场景化多版本这件事，成本结构上已经跑得通了」。</p><p>不要当作<strong>基准数据</strong>——不要拿 80% 去给自己的项目报价或立 KPI。</p></blockquote><p>「周期 3 天」相对更可信，因为<strong>时间比钱更难注水</strong>——一个项目做了几天，参与的人都知道。</p><hr><h2 id="_4-可复用套路" tabindex="-1">④ 可复用套路 <a class="header-anchor" href="#_4-可复用套路" aria-label="Permalink to &quot;④ 可复用套路&quot;">​</a></h2><ol><li><p>**先问「有几个场景」，再问「做几版」。**版本数不该拍脑袋定，应该由投放场景的数量倒推。有两类电梯就做两版，有五种人群就做五版。</p></li><li><p>**适配型批量和测试型批量要分开做。**前者靠人群判断分发，后者靠数据优胜劣汰。<strong>混在一起做，两件事都做不成。</strong></p></li><li><p><strong>场景变了，重写文案而不是换个说法。</strong>「上班困了」和「周末宅家」不是同一句话的两种表达，是<strong>两个不同的心理切入点</strong>。只改措辞不改洞察，等于没做适配。</p></li><li><p>**别人的效率数字，只看方向不看数值。**尤其是服务商和品牌方联合发布的降本比例。</p></li><li><p>**梯媒不需要 3 秒钩子。**投放环境决定创意结构，别把短视频的规矩搬过去。</p></li></ol><hr><h2 id="这个案例没有告诉我们的事" tabindex="-1">这个案例没有告诉我们的事 <a class="header-anchor" href="#这个案例没有告诉我们的事" aria-label="Permalink to &quot;这个案例没有告诉我们的事&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">缺失的信息比给出的更值得注意</p><table tabindex="0"><thead><tr><th>没公开</th><th>为什么重要</th></tr></thead><tbody><tr><td><strong>出片率</strong></td><td>3 天里生成了多少条废片？<a href="/cases/case-06-kalshi-veo">案例 06</a> 告诉我们真实值可能是 4%</td></tr><tr><td><strong>人力投入</strong></td><td>「3 天」是几个人的 3 天？1 人和 5 人差 5 倍</td></tr><tr><td><strong>画面怎么做的</strong></td><td>是真的生成了视频，还是模板套图 + 换文案？<strong>这两者的技术难度差一个量级</strong></td></tr><tr><td><strong>效果数据</strong></td><td>只公布了制作侧的降本增效，<strong>没有公布这些广告卖出去多少货</strong></td></tr></tbody></table><p>**最后一条最关键。**省钱和有效是两件事。一支便宜 80% 但没人记住的广告，不是胜利。</p></div><hr><h2 id="接着看" tabindex="-1">接着看 <a class="header-anchor" href="#接着看" aria-label="Permalink to &quot;接着看&quot;">​</a></h2><table tabindex="0"><thead><tr><th>本文的观察</th><th>对应的方法</th></tr></thead><tbody><tr><td>适配型批量 vs 测试型批量</td><td><a href="/method/ab-testing">A/B 创意批量测试</a></td></tr><tr><td>投放场景决定创意结构</td><td><a href="/method/ad-formats">片型图谱 · 按投放场景挑</a></td></tr><tr><td>效率数字要打折看</td><td><a href="/guide/landscape">AI 创意广告全景 · 常见认知误区</a></td></tr><tr><td>真实的出片率长什么样</td><td><a href="/cases/case-06-kalshi-veo">案例 06 · Kalshi</a></td></tr><tr><td>批量生产的一致性怎么控</td><td><a href="/cases/case-02-ecommerce-visual">案例 02 · 电商主图批量生产</a></td></tr></tbody></table><p><strong>参考来源</strong>：<a href="https://www.adquan.com/article/359105" target="_blank" rel="noreferrer">2026 年品牌广告制作指南 · 广告门</a> · <a href="https://36kr.com/p/3290471587885445" target="_blank" rel="noreferrer">AI 广告片进击：谁爱用、如何用、真有用？· 36氪</a></p>',37)])])}const b=r(d,[["render",e]]);export{c as __pageData,b as default};
